      SUBROUTINE BEAM1CC     FIRST-ORDER CONTRIBUTIONS TO BEAM MATRIXCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'ELM1B.CIN'      INCLUDE 'ELM1C.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM1E.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'SI.CIN'CC     LOCAL VARIABLESC      INTEGER  J, K, L1      REAL  ALPHX0, ALPHY0, BETX0, BETY0, EPSX0, EPSY0, SSCC-------------------------------------------------------------C     BEAM MATRIX CALCULATED FROM TRANSFER MATRIXC     AND PREVIOUS BEAM MATRIXC      CALL CAB(RT,RC2,SI)      DO 240 J = 1, 6      DO 240 K = 1, J      SS = 0.0      DO 235 L1 = 1, 6      SS = SS + RT(J,L1)*RC2(K,L1)  235 CONTINUE      SIT(J,K) = SS  240 CONTINUECC     PHASE ADVANCES FOR ACCELERATOR NOTATIONC      IF (.NOT. DOPH) GO TO 300      EPSX0 = SQRT(SI(1,1)*SI(2,2) - SI(2,1)**2)      EPSX = SIT(1,1)*SIT(2,2) - SIT(2,1)**2      IF (EPSX .GE. 0.0) THEN        EPSX = SQRT(EPSX)      ELSE        EPSX = 0.0      ENDIF      IF (EPSX0 .EQ. 0.0 .OR. EPSX .EQ. 0.0) THEN        DOPH = .FALSE.        GO TO 300      ENDIF      BETX0 = SI(1,1)/EPSX0      BETAX = SIT(1,1)/EPSX      ALPHX0 = - SI(2,1)/EPSX0      ALPHAX = - SIT(2,1)/EPSX      SNPX = RC2(1,2)/SQRT(BETX0*BETAX)      CSPX = RC2(1,1)*SQRT(BETX0/BETAX) - ALPHX0*SNPX      IF (CSPX .EQ. 0.0) THEN        IF (SNPX .GT. 0.0) THEN          PSIX = 0.5*PI        ELSE          PSIX = 1.5*PI        ENDIF      ELSE        PSIX = ATAN(SNPX/CSPX)      ENDIF      IF (RCP) PSIX = PSIX + PSIX1      IF (CSPX .LT. 0.0) PSIX = PSIX + PI  255 IF (PSIX .GE. PSIXO) GO TO 260      PSIX = PSIX + 2.0*PI      GO TO 255C  260 EPSY0 = SQRT(SI(3,3)*SI(4,4) - SI(4,3)**2)      EPSY = SIT(3,3)*SIT(4,4) - SIT(4,3)**2      IF (EPSY .GE. 0.0) THEN        EPSY = SQRT(EPSY)      ELSE        EPSY = 0.0      ENDIF      IF (EPSY0 .EQ. 0.0 .OR. EPSY .EQ. 0.0) THEN        DOPH = .FALSE.        GO TO 300      ENDIF      BETY0 = SI(3,3)/EPSY0      BETAY = SIT(3,3)/EPSY      ALPHY0 = - SI(4,3)/EPSY0      ALPHAY = - SIT(4,3)/EPSY      SNPY = RC2(3,4)/SQRT(BETY0*BETAY)      CSPY = RC2(3,3)*SQRT(BETY0/BETAY) - ALPHY0*SNPY      IF (CSPY .EQ. 0.0) THEN        IF (SNPY .GT. 0.0) THEN          PSIY = 0.5*PI        ELSE          PSIY = 1.5*PI        ENDIF      ELSE        PSIY = ATAN(SNPY/CSPY)      ENDIF      IF (RCP) PSIY = PSIY + PSIY1      IF (CSPY .LT. 0.0) PSIY = PSIY + PI  265 IF (PSIY .GE. PSIYO) GO TO 300      PSIY = PSIY + 2.0*PI      GO TO 265C  300 PSIXO = PSIX      PSIYO = PSIY  400 RETURN      END